const input = $input.first().json;
const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const priorityByFamily = Object.fromEntries((input.taxonomy_families || []).map((f) => [f.family_id, f.priority || 0]));
const needsByFamily = (input.training_needs || []).reduce((acc, n) => { (acc[n.family_id] ||= []).push(n.need_id); return acc; }, {});
const rows = [];
for (const offer of input.offers || []) {
  const title = norm(offer.normalized_title || offer.title);
  const matches = [];
  for (const kw of input.taxonomy_keywords || []) if (title.includes(norm(kw.normalized_keyword || kw.keyword))) matches.push({ family_id: kw.family_id, reason: 'G8N_CLASS_KEYWORD_MATCH' });
  const unique = [...new Set(matches.map((m) => m.family_id))];
  let status = 'unclassified'; let family_ids = []; let confidence = 0.2; let reasons = ['G8N_CLASS_NO_MATCH'];
  if (offer.job_code && offer.job_code_family_id) { status = 'classified'; family_ids = [offer.job_code_family_id]; confidence = 0.95; reasons = ['G8N_CLASS_CODE_MATCH']; }
  else if (unique.length === 1) { status = 'classified'; family_ids = unique; confidence = matches.length > 1 ? 0.85 : 0.8; reasons = [matches.length > 1 ? 'G8N_CLASS_MULTIPLE_CONSISTENT' : 'G8N_CLASS_KEYWORD_MATCH']; }
  else if (unique.length > 1) { status = 'ambiguous'; family_ids = unique.sort((a, b) => (priorityByFamily[b] || 0) - (priorityByFamily[a] || 0)); confidence = 0.45; reasons = ['G8N_CLASS_FAMILY_CONFLICT']; }
  const primary = status === 'classified' ? family_ids[0] : null;
  rows.push({ classification_key: `${offer.offer_key || offer.title}:${input.taxonomy_version}:${input.classifier_version}`, offer_key: offer.offer_key || null, classifier_version: input.classifier_version, taxonomy_version: input.taxonomy_version, job_family: primary, family_ids_json: JSON.stringify(family_ids), is_tension_job: primary ? Boolean((input.taxonomy_families || []).find((f) => f.family_id === primary)?.reference_tension) : false, training_need_ids_json: JSON.stringify(primary ? (needsByFamily[primary] || []) : []), confidence, reasons_json: JSON.stringify(reasons), classification_status: status, classified_at: new Date().toISOString() });
}
return [{ json: { ...input, job_classification_upserts: rows } }];
